"""Содержательные процедуры переносимых адаптеров gstack для rcode."""

WORKFLOWS = {}


def add(name, title, description, artifact, steps, checks, needs="", capability="native"):
    WORKFLOWS[name] = {
        "name": name, "title": title, "description": description,
        "artifact": artifact, "steps": steps.split("|"), "checks": checks.split("|"),
        "prerequisites": needs.split("|") if needs else [], "capability": capability,
    }


